import { cacheTag } from "next/cache";

export interface Post {
  id: number;
  title: string;
  content: string;
  createdAt: string;
}

const posts: Post[] = [
  { id: 1, title: "Welcome", content: "This is the first post!", createdAt: new Date().toISOString() },
];

export async function getPosts(): Promise<Post[]> {
  "use cache";
  cacheTag("posts");
  return posts;
}

export function addPost(title: string, content: string): Post {
  const id = posts.length > 0 ? Math.max(...posts.map((p) => p.id)) + 1 : 1;
  const post: Post = { id, title, content, createdAt: new Date().toISOString() };
  posts.push(post);
  return post;
}

"use server";

import { revalidateTag } from "next/cache";
import { addPost } from "./lib/posts";

export async function createPost(formData: FormData) {
  const title = formData.get("title") as string;
  const content = formData.get("content") as string;

  if (!title || !content) return;

  addPost(title, content);
  revalidateTag("posts");
}

import { getPosts } from "./lib/posts";
import { createPost } from "./actions";

export default async function Home() {
  const posts = await getPosts();

  return (
    <main>
      <h1>Posts</h1>

      <form action={createPost}>
        <input name="title" placeholder="Title" required />
        <textarea name="content" placeholder="Content" required />
        <button type="submit">Create Post</button>
      </form>

      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>{post.content}</p>
            <time>{post.createdAt}</time>
          </li>
        ))}
      </ul>
    </main>
  );
}

